pub struct AgentLoop<B: Browser> {
    browser: B,
    clients: LlmClients,
    router: Router,
    validator: Validator,
    policy: AgentPolicy,
    memory: Memory,
    task: String,
}

impl<B: Browser> AgentLoop<B> {
    pub fn new(browser: B, clients: LlmClients, task: impl Into<String>) -> Self {
        let policy = AgentPolicy::default();
        let memory = Memory::new(policy.memory.clone());
        Self {
            browser,
            clients,
            router: Router::default(),
            validator: Validator::default(),
            policy,
            memory,
            task: task.into(),
        }
    }

    pub fn with_plan(mut self, plan: impl Into<String>) -> Self {
        self.memory.set_plan(Some(plan.into()));
        self
    }

    pub fn with_policy(mut self, policy: AgentPolicy) -> Self {
        let plan = self.memory.plan().map(|value| value.to_string());
        self.policy = policy;
        self.memory = Memory::new(self.policy.memory.clone());
        self.memory.set_plan(plan);
        self
    }

    pub fn with_router(mut self, router: Router) -> Self {
        self.router = router;
        self
    }

    pub fn with_validator(mut self, validator: Validator) -> Self {
        self.validator = validator;
        self
    }

    pub fn memory(&self) -> &Memory {
        &self.memory
    }

    pub async fn shutdown(&self) -> Result<(), BrowserError> {
        self.browser.shutdown().await
    }

    pub async fn run(&mut self) -> Result<RunResult, AgentError> {
        enum StepControl {
            Continue,
            Done(Action),
        }

        let snapshot_start = Instant::now();
        let mut observation = match self.browser.snapshot().await {
            Ok(observation) => {
                telemetry::record_snapshot_duration(snapshot_start.elapsed());
                observation
            }
            Err(err) => {
                telemetry::record_snapshot_duration(snapshot_start.elapsed());
                tracing::error!(
                    event = "snapshot_error",
                    error_code = err.code,
                    error_message = %err.message
                );
                return Err(AgentError::Browser(err));
            }
        };
        self.memory.record_observation(observation.clone());

        for step_index in 0..self.policy.max_steps {
            let tier = self.router.tier();
            telemetry::inc_step();

            let step_span = tracing::info_span!(
                "step",
                step_index = step_index + 1,
                tier = ?tier,
                url = %observation.url,
                state_hash = ?observation.state_hash
            );

            let step_result = async {
                let step_start = Instant::now();
                let client = self.clients.client(tier);

                let action = match client
                    .propose_action(
                        &self.task,
                        self.memory.plan(),
                        &observation,
                        self.memory.history(),
                    )
                    .await
                {
                    Ok(action) => action,
                    Err(err) => {
                        let duration = step_start.elapsed();
                        telemetry::record_step_duration(duration);
                        tracing::error!(
                            event = "llm_error",
                            error_code = err.code,
                            error_message_len = err.message.chars().count(),
                            step_duration_ms = duration.as_millis() as u64
                        );
                        return Err(AgentError::Llm(err));
                    }
                };

                telemetry::inc_action(&action);
                tracing::info!(
                    event = "action_proposed",
                    action_type = telemetry::action_type(&action),
                    action = ?telemetry::ActionSummary::from(&action)
                );

                if let Err(errors) = self.validator.validate(&action, &observation) {
                    let error_count = errors.len();
                    telemetry::inc_validation_failure();
                    let mut result = validation_result(errors);
                    result.new_state_hash = Some(observation.state_hash.clone());
                    self.memory.record_step(action, result);
                    let tier_after = self.router.record(StepOutcome::Failure);
                    telemetry::set_no_progress_streak(self.router.counters().no_progress);
                    let duration = step_start.elapsed();
                    telemetry::record_step_duration(duration);
                    tracing::warn!(
                        event = "validation_failed",
                        error_count = error_count,
                        tier = ?tier_after,
                        step_duration_ms = duration.as_millis() as u64
                    );
                    return Ok(StepControl::Continue);
                }

                if matches!(action, Action::Done { .. }) {
                    let result = done_result(&observation);
                    self.memory.record_step(action.clone(), result);
                    let duration = step_start.elapsed();
                    telemetry::record_step_duration(duration);
                    tracing::info!(
                        event = "done",
                        step_duration_ms = duration.as_millis() as u64
                    );
                    return Ok(StepControl::Done(action));
                }

                let apply_start = Instant::now();
                let mut result = match self.browser.apply(&action).await {
                    Ok(result) => result,
                    Err(err) => {
                        let apply_duration = apply_start.elapsed();
                        telemetry::record_apply_duration(apply_duration);
                        let duration = step_start.elapsed();
                        telemetry::record_step_duration(duration);
                        tracing::error!(
                            event = "apply_error",
                            error_code = err.code,
                            error_message = %err.message,
                            step_duration_ms = duration.as_millis() as u64
                        );
                        return Err(AgentError::Browser(err));
                    }
                };
                let apply_duration = apply_start.elapsed();
                telemetry::record_apply_duration(apply_duration);
                if !result.ok {
                    telemetry::inc_apply_failure();
                }
                self.memory.record_step(action.clone(), result.clone());

                    target = null;
                }
            }
            if (!target) {
                return { ok: false, error: "not_found" };
            }
            let value = "";
            if ("value" in target) {
                try {
                    value = String(target.value ?? "");
                } catch (err) {
                    value = "";
                }
            }
            if (!value) {
                value = (target.innerText || target.textContent || "").trim();
            }
            return { ok: true, value };
        }
    "#
}

async fn focus_backend_node(page: &Page, backend_node_id: BackendNodeId) -> Result<(), ActionError> {
    let params = FocusParams::builder()
        .backend_node_id(backend_node_id)
        .build();
    page.execute(params)
        .await
        .map_err(|err| map_cdp_error(err, "focus"))?;
    Ok(())
}

async fn backend_node_click_point(
    page: &Page,
    backend_node_id: BackendNodeId,
) -> Result<(f64, f64), ActionError> {
    let model = page
        .execute(
            GetBoxModelParams::builder()
                .backend_node_id(backend_node_id)
                .build(),
        )
        .await
        .map_err(|err| map_cdp_error(err, "get_box_model"))?
        .result
        .model;
    quad_center(model.border.inner())
        .ok_or_else(|| ActionError::new("invalid_box_model", "invalid element box model"))
}

fn quad_center(quad: &[f64]) -> Option<(f64, f64)> {
    if quad.len() != 8 {
        return None;
    }
    let xs = [quad[0], quad[2], quad[4], quad[6]];
    let ys = [quad[1], quad[3], quad[5], quad[7]];
    let (min_x, max_x) = xs.iter().fold((xs[0], xs[0]), |acc, x| {
        (acc.0.min(*x), acc.1.max(*x))
    });
    let (min_y, max_y) = ys.iter().fold((ys[0], ys[0]), |acc, y| {
        (acc.0.min(*y), acc.1.max(*y))
    });
    Some(((min_x + max_x) / 2.0, (min_y + max_y) / 2.0))
}

fn parse_backend_node_id(id: &str) -> Result<BackendNodeId, ActionError> {
    let raw = id
        .strip_prefix("el_")
        .ok_or_else(|| ActionError::new("invalid_element_id", "missing el_ prefix"))?;
    let parsed = raw
        .parse::<i64>()
        .map_err(|_| ActionError::new("invalid_element_id", "invalid backend node id"))?;
    Ok(BackendNodeId::new(parsed))
}

fn resolve_backend_node_id(
    id: &str,
    element_map: Option<&HashMap<String, BackendNodeId>>,
) -> Result<BackendNodeId, ActionError> {
    if let Some(map) = element_map {
        return map.get(id).cloned().ok_or_else(|| {
            ActionError::new(
                "stale_element",
                format!("id {id} not found in latest observation"),
            )
        });
    }
    parse_backend_node_id(id)
}

async fn press_key(page: &Page, key: &str) -> Result<(), ActionError> {
    let key_definition = keys::get_key_definition(key)
        .ok_or_else(|| ActionError::new("invalid_key", format!("key not found: {key}")))?;
    let mut cmd = DispatchKeyEventParams::builder();
    let key_down_event_type = if let Some(txt) = key_definition.text {
        cmd = cmd.text(txt);
        DispatchKeyEventType::KeyDown
    } else if key_definition.key.len() == 1 {
        cmd = cmd.text(key_definition.key);
        DispatchKeyEventType::KeyDown
    } else {
        DispatchKeyEventType::RawKeyDown
    };

    cmd = cmd
        .r#type(DispatchKeyEventType::KeyDown)
        .key(key_definition.key)
        .code(key_definition.code)
        .windows_virtual_key_code(key_definition.key_code)
        .native_virtual_key_code(key_definition.key_code);

    page.execute(cmd.clone().r#type(key_down_event_type).build().unwrap())
        .await?;
    page.execute(cmd.r#type(DispatchKeyEventType::KeyUp).build().unwrap())
        .await?;
    Ok(())
}

